//! Oracle parity tests for the native SplineDist port, generated by
//! `scripts/splinedist/convert.py` from the pinned upstream model
//! (Zenodo 7193306, `bbbc038_10`; see the fixtures' `details.json` for
//! provenance and hashes): real `SplineDist2D.predict_instances` output
//! (123 instances, cropped to the real 520x696 frame), the exact network
//! input upstream consumed (csbdeep-normalized + reflect-padded), and
//! the exact keras head tensors at two shapes. End-to-end label
//! equality is EXACT (the decode is a port of upstream's own
//! nms.py/geom2d.py verified pixel-for-pixel in that generator).

// The gated module and the bundled ONNX only exist under the opt-in
// `splinedist-model` feature; the default build compiles this file to an
// empty test binary.
#![cfg(feature = "splinedist-model")]

use cp_anywhere::segmentation::splinedist::{
    decode, load_phi_basis, SplineDistOnnxModel, SplineDistThresholds, CONTOUR_SAMPLES,
    CONTROL_POINTS,
};
use std::path::{Path, PathBuf};

#[path = "support/npy.rs"]
mod npy;

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/splinedist_fixtures")
        .join(name)
}

fn model_bytes() -> Vec<u8> {
    std::fs::read(
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../src/cp_anywhere/data/splinedist/splinedist.onnx"),
    )
    .expect("src/cp_anywhere/data/splinedist/splinedist.onnx must be present in the repo")
}

/// (1, H, W, 1) NHWC fixture with one channel -> row-major (H, W) image.
fn fixture_image(path: &Path) -> (usize, usize, Vec<f32>) {
    let (shape, data) = npy::read_f32(path);
    assert_eq!(shape.len(), 4, "expected (1, H, W, 1): {shape:?}");
    assert_eq!((shape[0], shape[3]), (1, 1), "expected batch 1, channel 1");
    (shape[1], shape[2], data)
}

fn fixture_prob(path: &Path) -> (usize, usize, Vec<f32>) {
    fixture_image(path)
}

/// (1, H, W, 20) NHWC coord head -> channel-major (20 * H * W), optionally
/// cropped to the given (rows, cols) that the native runner applies.
fn fixture_coord(path: &Path) -> (usize, usize, Vec<f32>) {
    let (shape, data) = npy::read_f32(path);
    assert_eq!(shape.len(), 4, "expected (1, H, W, 20): {shape:?}");
    assert_eq!(
        (shape[0], shape[3]),
        (1, 20),
        "expected batch 1, 20 channels"
    );
    let (h, w, ch) = (shape[1], shape[2], shape[3]);
    let mut channels = Vec::with_capacity(ch * h * w);
    for c in 0..ch {
        for r in 0..h {
            for x in 0..w {
                channels.push(data[r * w * ch + x * ch + c]);
            }
        }
    }
    (h, w, channels)
}

/// Crop a keras NHWC head to the real-frame region (the last
/// (padded - real) rows/cols fall off at grid scale).
fn crop_head(data: &[f32], _h: usize, w: usize, ch: usize, rows: usize, cols: usize) -> Vec<f32> {
    let mut out = Vec::with_capacity(rows * cols * ch);
    for r in 0..rows {
        for c in 0..cols {
            for k in 0..ch {
                out.push(data[r * w * ch + c * ch + k]);
            }
        }
    }
    out
}

fn fixture_labels_i32(path: &Path) -> (Vec<usize>, Vec<i32>) {
    let npy = npy::read(path);
    assert_eq!(npy.descr, "<i4", "expecting int32 labels");
    let data: Vec<i32> = npy
        .data
        .chunks_exact(4)
        .map(|c| i32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    (npy.shape, data)
}

/// The real upstream network input (528x704 padded frame) must produce
/// heads within [1e-3, 5e-3] of the exact keras tensors upstream's own
/// predict consumed, and the second shape (the 128x128 probe) must do
/// the same through the dynamic ONNX axes.
#[test]
fn tract_heads_match_upstream_keras_on_both_shapes() {
    let (rows, cols, input) = fixture_image(&fixture("network_input.npy"));
    let real_rows = 520;
    let real_cols = 696;

    let net = SplineDistOnnxModel::from_bytes(model_bytes())
        .run_network(&input, rows, cols, real_rows, real_cols)
        .unwrap();

    // The native runner already crops the heads to the real frame; compare
    // against the keras tensors' correspondingly cropped region.
    let (prob_h_raw, prob_w_raw, prob_raw) = fixture_prob(&fixture("network_output_keras_0.npy"));
    let (coord_h_raw, coord_w_raw, coord_raw_nhwc) = {
        let (shape, data) = npy::read_f32(&fixture("network_output_keras_1.npy"));
        assert_eq!((shape[0], shape[3]), (1, 20));
        (shape[1], shape[2], data)
    };
    assert_eq!((prob_h_raw, prob_w_raw), (264, 352));
    assert_eq!((coord_h_raw, coord_w_raw), (264, 352));
    let prob_ref = crop_head(
        &prob_raw,
        prob_h_raw,
        prob_w_raw,
        1,
        net.ch_rows,
        net.ch_cols,
    );
    let coord_ref = {
        // (rows, cols, ch) -> channel-major, cropped to the real frame.
        let mut out = Vec::with_capacity(20 * net.ch_rows * net.ch_cols);
        for ch in 0..20usize {
            for r in 0..net.ch_rows {
                for c in 0..net.ch_cols {
                    out.push(coord_raw_nhwc[r * coord_w_raw * 20 + c * 20 + ch]);
                }
            }
        }
        out
    };
    assert_eq!(net.prob.len(), prob_ref.len());
    assert_eq!(net.coord_channels.len(), coord_ref.len());
    assert!(net.ch_rows * 2 >= real_rows && net.ch_cols * 2 >= real_cols);
    let max_prob_error = net
        .prob
        .iter()
        .zip(&prob_ref)
        .map(|(a, b)| (a - b).abs())
        .fold(0.0_f32, f32::max);
    let max_coord_error = net
        .coord_channels
        .iter()
        .zip(&coord_ref)
        .map(|(a, b)| (a - b).abs())
        .fold(0.0_f32, f32::max);
    assert!(max_prob_error < 1e-3, "prob head error {max_prob_error}");
    assert!(max_coord_error < 5e-3, "coord head error {max_coord_error}");

    // Second shape: the probe input exercises dynamic H/W axes.
    let (probe_rows, probe_cols, probe) = fixture_image(&fixture("probe_input.npy"));
    let net2 = SplineDistOnnxModel::from_bytes(model_bytes())
        .run_network(&probe, probe_rows, probe_cols, probe_rows, probe_cols)
        .unwrap();
    let (_, _, probe_prob_ref) = fixture_prob(&fixture("probe_output_keras_0.npy"));
    let (_, _, probe_coord_ref) = fixture_coord(&fixture("probe_output_keras_1.npy"));
    let max_prob_error = net2
        .prob
        .iter()
        .zip(&probe_prob_ref)
        .map(|(a, b)| (a - b).abs())
        .fold(0.0_f32, f32::max);
    let max_coord_error = net2
        .coord_channels
        .iter()
        .zip(&probe_coord_ref)
        .map(|(a, b)| (a - b).abs())
        .fold(0.0_f32, f32::max);
    assert!(
        max_prob_error < 1e-3,
        "probe prob head error {max_prob_error}"
    );
    assert!(
        max_coord_error < 5e-3,
        "probe coord head error {max_coord_error}"
    );
}

/// The full native path (tract heads on the recorded input -> crop ->
/// spline decode) must reproduce upstream's freshly-run
/// `predict_instances` label map EXACTLY (integer labels).
#[test]
fn native_decode_reproduces_upstream_labels_exactly() {
    let phi = load_phi_basis(&std::fs::read(fixture("phi_basis.npy")).unwrap()).unwrap();
    let (rows, cols, input) = fixture_image(&fixture("network_input.npy"));
    let real_rows = 520;
    let real_cols = 696;

    let net = SplineDistOnnxModel::from_bytes(model_bytes())
        .run_network(&input, rows, cols, real_rows, real_cols)
        .unwrap();
    let result = decode(
        &net.prob,
        &net.coord_channels,
        net.ch_rows,
        net.ch_cols,
        &phi,
        CONTOUR_SAMPLES,
        CONTROL_POINTS,
        &SplineDistThresholds::from_shipped_model(),
        real_rows,
        real_cols,
    )
    .unwrap();

    let (oracle_shape, oracle) = fixture_labels_i32(&fixture("labels_oracle.npy"));
    assert_eq!(oracle_shape, vec![real_rows, real_cols]);
    assert_eq!(result.object_count, 123);
    let mut mismatches = 0usize;
    let mut first: Option<(usize, usize, u32, i32)> = None;
    for (i, (&got, &want)) in result.labels.iter().zip(&oracle).enumerate() {
        if got != want as u32 {
            mismatches += 1;
            if first.is_none() {
                first = Some((i / real_cols, i % real_cols, got, want));
            }
        }
    }
    assert!(
        mismatches == 0,
        "label mismatches {mismatches}, first diff {first:?}"
    );
}

/// The 128x128 probe shape must decode deterministically without panic
/// (small frames exercise the b=2 trim and degenerate raster paths).
#[test]
fn decode_is_deterministic_and_panic_free_on_the_probe_shape() {
    let phi = load_phi_basis(&std::fs::read(fixture("phi_basis.npy")).unwrap()).unwrap();
    let (probe_rows, probe_cols, probe) = fixture_image(&fixture("probe_input.npy"));
    let net = SplineDistOnnxModel::from_bytes(model_bytes())
        .run_network(&probe, probe_rows, probe_cols, probe_rows, probe_cols)
        .unwrap();
    let first = decode(
        &net.prob,
        &net.coord_channels,
        net.ch_rows,
        net.ch_cols,
        &phi,
        CONTOUR_SAMPLES,
        CONTROL_POINTS,
        &SplineDistThresholds::from_shipped_model(),
        probe_rows,
        probe_cols,
    )
    .unwrap();
    let second = decode(
        &net.prob,
        &net.coord_channels,
        net.ch_rows,
        net.ch_cols,
        &phi,
        CONTOUR_SAMPLES,
        CONTROL_POINTS,
        &SplineDistThresholds::from_shipped_model(),
        probe_rows,
        probe_cols,
    )
    .unwrap();
    assert_eq!(first.labels, second.labels);
    assert_eq!(first.object_count, second.object_count);
}
